#!/usr/bin/env bun
/**
 * aide-wrapper.ts - Ensures aide binary exists before executing
 *
 * Called by an assistant's MCP server configuration.
 * Finds the aide binary, downloads it if missing, then delegates to it.
 *
 * Plugin root resolution order:
 *   1. AIDE_PLUGIN_ROOT  (canonical, platform-agnostic)
 *   2. CLAUDE_PLUGIN_ROOT (set by Claude Code)
 *   3. SCRIPT_DIR/..      (fallback: infer from wrapper location)
 *
 * Binary resolution order (first hit wins):
 *   1. Bundled via npm optionalDependencies:
 *      @jmylchreest/aide-binary-<platform>-<arch>/bin/aide[.exe], located
 *      with node's resolution algorithm and a node_modules walk-up. Package
 *      managers HOIST optional deps next to the plugin, not inside it, so
 *      <plugin-root>/node_modules/ is the one place it is never found.
 *   2. PLUGIN_ROOT/bin/aide[.exe]  (legacy: downloaded by previous wrapper run)
 *   3. Downloaded fresh into PLUGIN_ROOT/bin/  (fallback when neither exists)
 *
 * The bundled path is populated by `npm install` for OpenCode/Codex users
 * (zero-config, offline-after-install). Claude Code users — whose plugin
 * distribution does not support npm optionalDependencies — fall through
 * to the legacy download path; Claude's per-version cache layout makes
 * that path work correctly.
 *
 * This file is deliberately self-contained: it runs before `bun install`
 * has necessarily populated node_modules, so it duplicates the resolution
 * logic in src/lib/binary-resolve.ts rather than importing it. The two are
 * pinned together by src/test/binary-resolve.test.ts.
 *
 * Lives at: <plugin-root>/bin/aide-wrapper.ts
 * Logs written to: .aide/_logs/wrapper.log
 */

import { execFileSync, spawnSync } from "child_process";
import {
  existsSync,
  mkdirSync,
  readFileSync,
  realpathSync,
  appendFileSync,
  unlinkSync,
  writeFileSync,
  rmdirSync,
} from "fs";
import { createRequire } from "module";
import { dirname, join, resolve, sep } from "path";
import { fileURLToPath } from "url";

const isWindows = process.platform === "win32";
const EXT = isWindows ? ".exe" : "";

// Resolve symlinks so that invoking via node_modules/.bin/aide-wrapper
// (which is a symlink to the real package) gives us the real package dir.
const __filename = fileURLToPath(import.meta.url);
let scriptDir: string;
try {
  scriptDir = dirname(realpathSync(__filename));
} catch {
  scriptDir = dirname(__filename);
}

// The package this wrapper physically belongs to. Unlike PLUGIN_ROOT it
// cannot be pointed elsewhere by an env var inherited from a parent session,
// so it is the trustworthy anchor for "which install am I part of".
const SELF_ROOT = resolve(scriptDir, "..");

const PLUGIN_ROOT =
  process.env.AIDE_PLUGIN_ROOT ||
  process.env.CLAUDE_PLUGIN_ROOT ||
  SELF_ROOT;

const BINARY = join(PLUGIN_ROOT, "bin", `aide${EXT}`);
const BIN_DIR = join(PLUGIN_ROOT, "bin");

// Per-arch npm package holding the bundled binary for this host.
const ARCH_PKG: Record<string, string> = {
  "linux-x64": "linux-amd64",
  "linux-arm64": "linux-arm64",
  "darwin-x64": "darwin-amd64",
  "darwin-arm64": "darwin-arm64",
  "win32-x64": "windows-amd64",
  "win32-arm64": "windows-arm64",
};
const BINARY_PKG = (() => {
  const suffix = ARCH_PKG[`${process.platform}-${process.arch}`];
  return suffix ? `@jmylchreest/aide-binary-${suffix}` : null;
})();

/**
 * Find the binary npm installed via optionalDependencies.
 *
 * Package managers hoist optional deps to the install root, so the binary
 * is a *sibling* of the plugin package:
 *
 *   node_modules/@jmylchreest/aide-plugin/               <- SELF_ROOT
 *   node_modules/@jmylchreest/aide-binary-linux-amd64/bin/aide
 *
 * Node's resolver handles that natively; the walk-up covers layouts where
 * it can't run (bun's ESM cache, Yarn PnP-free installs, dev checkouts).
 */
function resolveBundledBinary(): string | null {
  if (!BINARY_PKG) return null;
  const subPath = join(...BINARY_PKG.split("/"), "bin", `aide${EXT}`);

  try {
    const resolved = createRequire(import.meta.url).resolve(
      `${BINARY_PKG}/bin/aide${EXT}`,
    );
    if (existsSync(resolved)) return resolved;
  } catch {
    // Not resolvable from here — fall through to the filesystem walk.
  }

  const roots = SELF_ROOT === PLUGIN_ROOT ? [SELF_ROOT] : [SELF_ROOT, PLUGIN_ROOT];
  for (const root of roots) {
    let dir = resolve(root);
    for (;;) {
      const nested = join(dir, "node_modules", subPath);
      if (existsSync(nested)) return nested;
      if (dir.endsWith(`${sep}node_modules`)) {
        const hoisted = join(dir, subPath);
        if (existsSync(hoisted)) return hoisted;
      }
      const parent = dirname(dir);
      if (parent === dir) break;
      dir = parent;
    }
  }
  return null;
}

// Setup logging
const LOG_DIR = join(PLUGIN_ROOT, ".aide", "_logs");
const LOG_FILE = join(LOG_DIR, "wrapper.log");
try {
  mkdirSync(LOG_DIR, { recursive: true });
} catch {
  // ignore
}

function log(msg: string): void {
  const timestamp = new Date().toISOString().replace("T", " ").replace(/\..+/, "");
  const line = `[${timestamp}] [aide-wrapper] ${msg}`;
  process.stderr.write(line + "\n");
  try {
    appendFileSync(LOG_FILE, line + "\n");
  } catch {
    // ignore log write failures
  }
}

/**
 * Compare semantic versions: returns true if a >= b
 */
function versionGte(a: string, b: string): boolean {
  const pa = a.split(".").map(Number);
  const pb = b.split(".").map(Number);
  for (let i = 0; i < 3; i++) {
    const va = pa[i] || 0;
    const vb = pb[i] || 0;
    if (va > vb) return true;
    if (va < vb) return false;
  }
  return true;
}

/**
 * Get the version string from the aide binary
 */
function getBinaryVersion(binary: string): string | null {
  try {
    const output = execFileSync(binary, ["version"], {
      stdio: "pipe",
      timeout: 5000,
    })
      .toString()
      .trim();
    const match = output.match(
      /(\d+\.\d+\.\d+(?:-[a-zA-Z0-9.+]+)?)/,
    );
    return match ? match[1] : null;
  } catch {
    return null;
  }
}

/**
 * Read the plugin version from plugin.json or package.json.
 *
 * SELF_ROOT is consulted first: it is the package this wrapper was shipped
 * in, so it describes the code actually running. PLUGIN_ROOT can point at a
 * different (often older) install via an inherited env var.
 */
function getPluginVersion(): string | null {
  const roots = SELF_ROOT === PLUGIN_ROOT ? [SELF_ROOT] : [SELF_ROOT, PLUGIN_ROOT];
  for (const root of roots) {
    for (const relPath of [".claude-plugin/plugin.json", "package.json"]) {
      try {
        const content = readFileSync(join(root, relPath), "utf-8");
        const match = content.match(/"version"\s*:\s*"(\d+\.\d+\.\d+)/);
        if (match && match[1] !== "0.0.0") return match[1];
      } catch {
        // skip
      }
    }
  }
  return null;
}

/**
 * Check if the binary exists and is executable
 */
function binaryExists(): boolean {
  if (!existsSync(BINARY)) return false;
  // On Windows, existence is sufficient (no execute bit)
  if (isWindows) return true;
  try {
    execFileSync(BINARY, ["version"], { stdio: "pipe", timeout: 5000 });
    return true;
  } catch {
    // Binary exists but can't execute — might need re-download
    return false;
  }
}

/**
 * Check whether a process is still running. Signal 0 performs the
 * existence check without delivering a signal; EPERM means the process
 * exists but belongs to another user, so it counts as alive.
 */
function isPidAlive(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch (err: unknown) {
    return (err as { code?: string })?.code === "EPERM";
  }
}

function removeLock(lockPath: string): void {
  try {
    unlinkSync(join(lockPath, "pid"));
  } catch { /* ignore */ }
  try {
    // rmdir only works on empty dirs — that's what we want
    rmdirSync(lockPath);
  } catch { /* ignore */ }
}

/**
 * Simple cross-platform file lock.
 * Uses mkdir as an atomic operation (works on all platforms).
 * A lock whose owning pid is dead is reclaimed immediately, so a download
 * that crashed or was killed (e.g. by an MCP client's startup timeout)
 * can never wedge future startups.
 * The default timeout stays below common MCP startup timeouts (~30s) so
 * the force-remove fallback runs before the client gives up on us.
 * Returns a cleanup function to release the lock.
 */
function acquireLock(lockPath: string, timeoutMs: number = 20000): () => void {
  const start = Date.now();
  const pollMs = 200;
  let forced = false;

  while (true) {
    try {
      mkdirSync(lockPath);
      // Write our PID so waiters can detect a dead owner
      try {
        writeFileSync(join(lockPath, "pid"), String(process.pid));
      } catch {
        // ignore
      }
      return () => removeLock(lockPath);
    } catch (err: unknown) {
      if (
        !(
          err &&
          typeof err === "object" &&
          "code" in err &&
          (err as { code: string }).code === "EEXIST"
        )
      ) {
        throw err;
      }

      // Lock held — reclaim it if the owner is provably dead. A missing
      // or unreadable pid file may just mean the owner is between mkdir
      // and writeFileSync, so that case is left to the timeout below.
      try {
        const pid = Number(readFileSync(join(lockPath, "pid"), "utf-8").trim());
        if (Number.isFinite(pid) && pid > 0 && pid !== process.pid && !isPidAlive(pid)) {
          log(`Reclaiming stale download lock (owner pid ${pid} is dead)`);
          removeLock(lockPath);
          continue;
        }
      } catch { /* pid file unreadable — fall through to timeout */ }

      if (Date.now() - start > timeoutMs) {
        if (forced) {
          log("ERROR: Timed out waiting for download lock");
          throw new Error("Timed out waiting for download lock");
        }
        log("Timed out waiting for download lock — force-removing and retrying");
        forced = true;
        removeLock(lockPath);
        continue;
      }
      // Poll — use Bun.sleepSync for cross-platform millisecond sleep
      Bun.sleepSync(pollMs);
    }
  }
}

/**
 * Download the aide binary using the TypeScript downloader
 */
function downloadBinary(): void {
  const LOCKDIR = join(BIN_DIR, ".aide-download.lock");

  // Resolve the downloader script — prefer src/ (dev) but fall back to dist/ (npm install)
  let downloader: string;
  if (existsSync(join(PLUGIN_ROOT, "src", "lib", "aide-downloader.ts"))) {
    downloader = join(PLUGIN_ROOT, "src", "lib", "aide-downloader.ts");
  } else if (existsSync(join(PLUGIN_ROOT, "dist", "lib", "aide-downloader.js"))) {
    downloader = join(PLUGIN_ROOT, "dist", "lib", "aide-downloader.js");
  } else {
    log(`ERROR: Cannot find aide-downloader in src/ or dist/ under ${PLUGIN_ROOT}`);
    process.exit(1);
  }

  // Remove stale/outdated binary before locking
  if (existsSync(BINARY)) {
    log("Removing outdated binary before download");
    try {
      unlinkSync(BINARY);
    } catch {
      // ignore
    }
  }

  const releaseLock = acquireLock(LOCKDIR);
  try {
    // Re-check after acquiring lock — another process may have finished the download
    if (existsSync(BINARY)) {
      log("Binary appeared while waiting for lock (downloaded by another process)");
      return;
    }

    log("Downloading binary...");
    log(`Using downloader: ${downloader}`);

    // Determine runner based on file extension
    let runner: string;
    let runnerArgs: string[];

    if (downloader.endsWith(".ts")) {
      runner = "bun";
      runnerArgs = [downloader, "--dest", BIN_DIR];
    } else {
      runner = "node";
      runnerArgs = [downloader, "--dest", BIN_DIR];
    }

    // Use cross-spawn for cross-platform compatibility (lazy import to
    // survive missing node_modules during bootstrap).
    // Downloader stdout is redirected to our stderr: when we run as an MCP
    // server, stdout is the JSON-RPC channel and must stay clean.
    const crossSpawn = require("cross-spawn");
    const result = crossSpawn.sync(runner, runnerArgs, {
      stdio: ["ignore", 2, "inherit"],
      timeout: 120000,
    });

    if (result.status !== 0) {
      log("ERROR: Downloader failed");
      process.exit(1);
    }

    if (!existsSync(BINARY)) {
      log("ERROR: Binary not found after download");
      process.exit(1);
    }
  } finally {
    releaseLock();
  }

  log(`Binary ready at ${BINARY}`);
}

// --- Ensure dependencies ---

// After a Claude Code marketplace autoUpdate (git pull), node_modules/
// may be missing since it's gitignored. Detect and self-heal before any
// imports that depend on npm packages (e.g. 'which', 'cross-spawn').
//
// Resolvability is the test, not the presence of PLUGIN_ROOT/node_modules:
// in an npm install our dependencies are hoisted to the install root, so
// that directory is legitimately absent and running `bun install` there
// would be pure waste (and noisy failures when offline).
function dependenciesResolvable(): boolean {
  try {
    const req = createRequire(import.meta.url);
    req.resolve("cross-spawn");
    return true;
  } catch {
    return false;
  }
}

function ensureDependencies(): void {
  if (dependenciesResolvable()) return;
  const nodeModules = join(PLUGIN_ROOT, "node_modules");
  if (!existsSync(nodeModules)) {
    log("node_modules missing — running bun install to restore dependencies");
    try {
      const result = spawnSync("bun", ["install", "--frozen-lockfile"], {
        cwd: PLUGIN_ROOT,
        stdio: ["ignore", "pipe", "pipe"],
        timeout: 60000,
      });
      if (result.status === 0) {
        log("bun install completed successfully");
      } else {
        const stderr = result.stderr?.toString().trim();
        log(`WARNING: bun install failed (status ${result.status}): ${stderr}`);
      }
    } catch (err) {
      log(`WARNING: bun install error: ${err}`);
    }
  }
}

ensureDependencies();

// --- Main ---

log(
  `Starting wrapper (pid=${process.pid}, args=${process.argv.slice(2).join(" ")})`,
);
log(`PLUGIN_ROOT=${PLUGIN_ROOT}`);
log(`SELF_ROOT=${SELF_ROOT}`);
log(`BINARY=${BINARY}`);

// Bundled binary: installed by npm via optionalDependencies, pinned to the
// exact plugin version, so npm owns its lifecycle (install = upgrade). We
// still verify the version — a hoisted resolution can land on a different
// install's copy, and silently running the wrong binary is the exact bug
// class this whole mechanism exists to kill.
let bundledBinary = resolveBundledBinary();
log(`BUNDLED_BINARY=${bundledBinary ?? "(none — using legacy download path)"}`);

if (bundledBinary) {
  const pluginVersion = getPluginVersion();
  const bundledVersion = getBinaryVersion(bundledBinary);
  if (!bundledVersion) {
    log("WARNING: bundled binary is not executable, falling back to download path");
    bundledBinary = null;
  } else if (pluginVersion && !versionGte(bundledVersion.split("-")[0], pluginVersion)) {
    log(
      `WARNING: bundled binary v${bundledVersion} is older than plugin v${pluginVersion} ` +
        `(stale optionalDependency?), falling back to download path`,
    );
    bundledBinary = null;
  } else {
    log(
      `Using bundled binary v${bundledVersion} (plugin v${pluginVersion ?? "unknown"})`,
    );
  }
}

if (!bundledBinary) {
  let needsDownload = false;

  if (!binaryExists()) {
    needsDownload = true;
    log("Binary not found or not executable");
  } else {
    const binaryVersion = getBinaryVersion(BINARY);
    log(`Binary version: ${binaryVersion ?? "unknown"}`);

    if (binaryVersion && binaryVersion.includes("-dev.")) {
      // Dev build — check base version against plugin version
      const baseVersion = binaryVersion.split("-")[0];
      const pluginVersion = getPluginVersion();

      if (pluginVersion && versionGte(baseVersion, pluginVersion)) {
        log(
          `Dev build v${binaryVersion} (base ${baseVersion} >= plugin v${pluginVersion}), using local build`,
        );
      } else {
        needsDownload = true;
        log(
          `Dev build v${binaryVersion} is older than plugin v${pluginVersion ?? "unknown"}, re-downloading`,
        );
      }
    } else {
      const pluginVersion = getPluginVersion();
      if (pluginVersion && binaryVersion && !versionGte(binaryVersion, pluginVersion)) {
        needsDownload = true;
        log(
          `Release binary v${binaryVersion} is older than plugin v${pluginVersion}, re-downloading`,
        );
      } else {
        log(`Release binary v${binaryVersion ?? "unknown"} (plugin v${pluginVersion ?? "unknown"})`);
      }
    }
  }

  if (needsDownload) {
    downloadBinary();
  }
}

// Execute the aide binary, replacing this process
const execBinary = bundledBinary ?? BINARY;
log(`Executing: ${execBinary} ${process.argv.slice(2).join(" ")}`);

// Args are passed as an argv array, never through a shell.
const result = spawnSync(execBinary, process.argv.slice(2), {
  stdio: "inherit",
  env: process.env,
});

// Forward the exit code
process.exit(result.status ?? 1);

#!/usr/bin/env bun
/**
 * aide CLI — install/uninstall the aide plugin for OpenCode and Codex CLI.
 *
 * Usage:
 *   aide-plugin install [--platform codex|opencode]   # Install for detected platform
 *   aide-plugin uninstall [--platform codex|opencode]  # Remove from platform config
 *   aide-plugin status [--platform codex|opencode]     # Show installation status
 *   aide-plugin mcp                                    # Start MCP server
 *   aide-plugin hook <name>                            # Dispatch hook (Codex CLI)
 */

import { install } from "./install.js";
import { uninstall } from "./uninstall.js";
import { status } from "./status.js";
import { mcp } from "./mcp.js";
import { dispatchHook, listHooks } from "./hook.js";

const args = process.argv.slice(2);
const command = args[0];

type Platform = "opencode" | "codex";

function detectPlatform(): Platform {
  const idx = args.indexOf("--platform");
  if (idx !== -1 && args[idx + 1]) {
    const val = args[idx + 1] as string;
    if (val === "codex" || val === "opencode") return val;
    console.error(`Unknown platform: ${val}. Use "opencode" or "codex".`);
    process.exit(1);
  }

  // Positional form: `install codex`, `status opencode`
  if (["install", "uninstall", "status"].includes(command ?? "")) {
    const pos = args[1];
    if (pos && !pos.startsWith("-")) {
      if (pos === "codex" || pos === "opencode") return pos;
      console.error(`Unknown platform: ${pos}. Use "opencode" or "codex".`);
      process.exit(1);
    }
  }

  if (process.env.CODEX_HOME || process.env.CODEX_SANDBOX_TYPE) return "codex";

  return "opencode";
}

function printUsage(): void {
  console.log(`aide - AI Development Environment plugin for OpenCode and Codex CLI

Usage:
  aide-plugin install     Install aide plugin (auto-detects platform)
  aide-plugin uninstall   Remove aide plugin from platform config
  aide-plugin status      Show current installation status
  aide-plugin mcp         Start MCP server (delegates to aide-wrapper)
  aide-plugin hook <name> Dispatch a hook by name (used by Codex hooks.json)
  aide-plugin --help      Show this help message

Options:
  --platform codex|opencode   Target platform (also accepted positionally,
                              e.g. \`install codex\`; auto-detected if omitted)
  --project                   Apply to project-level config instead of global
  --no-mcp                    Skip MCP server registration (plugin only)

Available hooks:
  ${listHooks().join(", ")}

Examples:
  bunx @jmylchreest/aide-plugin install
  aide-plugin install --platform codex
  aide-plugin install --project
  aide-plugin hook session-start`);
}

async function main(): Promise<void> {
  const flags = {
    project: args.includes("--project"),
    noMcp: args.includes("--no-mcp"),
    platform: detectPlatform(),
  };

  switch (command) {
    case "install":
      await install(flags);
      break;
    case "uninstall":
      await uninstall(flags);
      break;
    case "status":
      await status(flags);
      break;
    case "mcp":
      await mcp(args.slice(1));
      break;
    case "hook": {
      const hookName = args[1];
      if (!hookName) {
        console.error(
          `Missing hook name.\nAvailable hooks: ${listHooks().join(", ")}`,
        );
        process.exit(1);
      }
      await dispatchHook(hookName);
      break;
    }
    case "--help":
    case "-h":
    case "help":
      printUsage();
      break;
    default:
      if (command) {
        console.error(`Unknown command: ${command}\n`);
      }
      printUsage();
      process.exit(command ? 1 : 0);
  }
}

main().catch((err) => {
  console.error(`Error: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(1);
});

/**
 * Core module — platform-agnostic aide logic.
 *
 * This module contains shared business logic used by both
 * Claude Code hooks (src/hooks/) and the OpenCode plugin (src/opencode/).
 */

export * from "./types.js";
export * from "./aide-client.js";
export * from "./session-init.js";
export * from "./skill-matcher.js";
export * from "./tool-tracking.js";
export * from "./persistence-logic.js";
export * from "./session-summary-logic.js";
export * from "./pre-compact-logic.js";
export * from "./partial-memory.js";
export * from "./cleanup.js";
export * from "./mcp-sync.js";
export * from "./tool-enforcement.js";

/**
 * aide OpenCode plugin entry point.
 *
 * Provides first-class integration with OpenCode (opencode.ai),
 * reusing the same core logic as the Claude Code hooks.
 *
 * Usage:
 *   - As a local plugin: copy/symlink to .opencode/plugins/
 *   - As an npm package: add "@jmylchreest/aide-plugin" to opencode.json
 *
 * Environment variables:
 *   AIDE_FORCE_INIT=1  Force aide initialization even in non-git directories.
 *                      By default, aide skips initialization when no .git/ or
 *                      .aide/ directory is found. Set this in the MCP server's
 *                      "environment" config to always create .aide/ in the
 *                      working directory.
 *
 * @example opencode.json
 * ```json
 * {
 *   "$schema": "https://opencode.ai/config.json",
 *   "plugin": ["@jmylchreest/aide-plugin"],
 *   "mcp": {
 *     "aide": {
 *       "type": "local",
 *       "command": ["bunx", "-y", "@jmylchreest/aide-plugin", "mcp"],
 *       "enabled": true
 *     }
 *   }
 * }
 * ```
 */

import { dirname, join } from "path";
import { fileURLToPath } from "url";
import { createHooks } from "./hooks.js";
import { isDebugEnabled } from "../lib/logger.js";
import { resolveProjectRoot } from "./resolve-root.js";
import type { Plugin, PluginInput, Hooks } from "./types.js";

// Resolve the plugin package root so we can find bundled skills.
// Works whether running from source (repo) or installed via npm.
const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
// index.ts lives in src/opencode/, so the package root is two levels up.
const pluginRoot = join(__dirname, "..", "..");

if (!process.env.AIDE_PLUGIN_ROOT) {
  process.env.AIDE_PLUGIN_ROOT = pluginRoot;
}

export const AidePlugin: Plugin = async (ctx: PluginInput): Promise<Hooks> => {
  // Log raw plugin input BEFORE any resolution for diagnostics.
  // This is the key to understanding what OpenCode actually passes.
  const rawLog = [
    `aide plugin init (raw ctx):`,
    `  ctx.directory = ${JSON.stringify(ctx.directory)}`,
    `  ctx.worktree  = ${JSON.stringify(ctx.worktree)}`,
    `  ctx.project   = ${JSON.stringify(ctx.project, null, 2)?.split("\n").join("\n  ")}`,
  ].join("\n");

  // Best-effort log to OpenCode's log system
  try {
    await ctx.client.app.log({
      body: { service: "aide", level: "info", message: rawLog },
    });
  } catch {
    // Plugin may be called before the client is fully ready
  }

  // Also log to stderr when debugging
  if (isDebugEnabled()) console.error(rawLog);

  const resolved = resolveProjectRoot(ctx);

  const forceInit = !!process.env.AIDE_FORCE_INIT;
  const resolvedLog = `aide plugin resolved: root=${resolved.root} hasProjectRoot=${resolved.hasProjectRoot}${forceInit ? " (AIDE_FORCE_INIT=1)" : ""}`;
  try {
    await ctx.client.app.log({
      body: { service: "aide", level: "info", message: resolvedLog },
    });
  } catch {
    // non-fatal
  }
  if (isDebugEnabled()) console.error(resolvedLog);

  return createHooks(resolved.root, ctx.worktree, ctx.client, pluginRoot, {
    skipInit: !resolved.hasProjectRoot,
  });
};

export default AidePlugin;

